'use strict';
const pop=globalThis.JerryPop,view=id=>document.getElementById(id);let machine=null,binary=null,session=null;
function revisions(){view('revisions').replaceChildren();if(!session)return;for(const revision of session.revisions){const option=document.createElement('option');option.value=String(revision.version);option.textContent='Revision '+revision.version+(revision.version===session.activeVersion?' · active':'');view('revisions').append(option);}view('revisions').value=String(session.activeVersion);}
function activate(){machine=session.machine;binary=session.binary;for(const id of ['step','run','feed-button','binary'])view(id).disabled=false;revisions();report();}
function report(){if(!machine)return;view('status').textContent=machine.status+' · '+machine.steps+' instructions'+(machine.error?' · '+machine.error:'');view('output').textContent=new TextDecoder().decode(new Uint8Array(machine.output));view('state').textContent=JSON.stringify({pc:machine.pc,registers:Array.from(machine.registers),remainingInput:machine.input.length-machine.inputOffset,drivers:Array.from(machine.ports.devices.values())},null,2);}
function invalidate(){machine=null;binary=null;for(const id of ['step','run','feed-button','binary'])view(id).disabled=true;view('status').textContent='Source or attachments changed. Assemble to create a new machine.';view('output').textContent='';view('state').textContent='';}
function attempt(fn){try{fn();report();}catch(e){view('status').textContent=e.message;}}
function restoreEditor(){const revision=session.current();view('source').value=revision.source;view('input').value=revision.input.join(' ');for(const name of Object.keys(pop.driverIds))view(name).checked=revision.drivers.includes(name);activate();}
for(const program of globalThis.KerotProgramLibrary){const option=document.createElement('option');option.value=program.id;option.textContent=program.name;view('program').append(option);}
view('load-program').addEventListener('click',()=>attempt(()=>{const program=globalThis.KerotProgramLibrary.find(p=>p.id===view('program').value);if(!program)throw Error('Unknown program');invalidate();view('source').value=program.source;view('input').value=program.input.join(' ');for(const name of Object.keys(pop.driverIds))view(name).checked=program.drivers.includes(name);view('status').textContent='Source loaded. Assemble or record an edited revision to execute.';}));
view('revise').addEventListener('click',()=>attempt(()=>{if(!session)throw Error('Assemble a session first');session.revise(view('source').value,pop.parseBytes(view('input').value),Object.keys(pop.driverIds).filter(name=>view(name).checked));restoreEditor();}));
view('revision-import').addEventListener('click',()=>attempt(()=>{const candidate=globalThis.JerryPopReinterpretation.Session.import(view('revision-json').value);session=candidate;restoreEditor();}));
for(const mode of globalThis.OstarQuiltProgram.manifest.modes){const option=document.createElement('option');option.value=String(mode.code);option.textContent=mode.name;view('mode').append(option);}
function example(){invalidate();const mode=globalThis.OstarQuiltProgram.manifest.modes[Number(view('mode').value)];view('source').value=globalThis.OstarQuiltProgram.source;view('input').value=[(mode.code>>2)&1,(mode.code>>1)&1,mode.code&1,...mode.payload.map(()=>1)].join(' ');}
view('example').addEventListener('click',example);view('source').addEventListener('input',invalidate);for(const name of Object.keys(pop.driverIds))view(name).addEventListener('change',invalidate);
view('assemble').addEventListener('click',()=>{invalidate();attempt(()=>{const names=Object.keys(pop.driverIds).filter(name=>view(name).checked);const candidate=new globalThis.JerryPopReinterpretation.Session(view('source').value,pop.parseBytes(view('input').value),names);session=candidate;activate();});});view('step').addEventListener('click',()=>attempt(()=>{machine.step();}));view('run').addEventListener('click',()=>attempt(()=>{machine.run(1000);}));view('feed-button').addEventListener('click',()=>attempt(()=>{machine.feed(pop.parseBytes(view('feed').value));view('feed').value='';}));
view('binary').addEventListener('click',()=>{if(!binary)return;const url=URL.createObjectURL(new Blob([binary],{type:'application/octet-stream'})),link=document.createElement('a');link.href=url;link.download='jerry-pop.k0';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});example();
view('reinterpret').addEventListener('click',()=>attempt(()=>{if(!session)throw Error('Assemble a session first');session.reinterpret(view('source').value);const revision=session.current();view('input').value=revision.input.join(' ');for(const name of Object.keys(pop.driverIds))view(name).checked=revision.drivers.includes(name);activate();}));
view('replay').addEventListener('click',()=>attempt(()=>{if(!session)throw Error('Assemble a session first');session.replay(view('revisions').value);const revision=session.current();view('source').value=revision.source;view('input').value=revision.input.join(' ');for(const name of Object.keys(pop.driverIds))view(name).checked=revision.drivers.includes(name);activate();}));
view('revision-export').addEventListener('click',()=>{if(!session){view('status').textContent='Assemble a session first';return;}const url=URL.createObjectURL(new Blob([session.export()],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='jerry-pop-revisions.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});

for(const template of globalThis.JerryPopTemplates.templates){const option=document.createElement('option');option.value=template.id;option.textContent=template.name;view('template').append(option);}
view('load-template').addEventListener('click',()=>attempt(()=>{const template=globalThis.JerryPopTemplates.instantiate(view('template').value);invalidate();view('source').value=template.source;view('input').value=template.input.join(' ');for(const name of Object.keys(pop.driverIds))view(name).checked=template.drivers.includes(name);view('template-description').textContent=template.description;view('status').textContent='Template loaded. Assemble to capture its input and drivers.';}));
